function accountProfile(){return window.moodnoteProfile||{}}
function renderAccountExtras(){
 const profile=accountProfile(),user=window.moodnoteUser,panel=document.getElementById('account-panels');
 document.querySelector('.account-note').insertAdjacentHTML('beforebegin',`<nav class="account-nav" aria-label="마이페이지 메뉴"><button data-account-scroll="my-orders">주문내역</button><button data-account-scroll="my-favorites">찜한 상품</button><button data-account-scroll="my-coupons">쿠폰함</button><button data-account-scroll="my-address">배송지 관리</button><button data-account-scroll="my-profile">회원정보 수정</button><button data-account-scroll="my-inquiries">1:1 문의</button></nav>`);
 panel.insertAdjacentHTML('beforeend',`<section class="account-section" id="my-coupons" hidden><div class="account-section-head"><h2>쿠폰함</h2><span>0개</span></div><div class="account-empty"><span aria-hidden="true">%</span><h3>사용할 수 있는 쿠폰이 없어요</h3><p>새 쿠폰이 발급되면 이곳에서 사용 조건과 만료일을 확인할 수 있습니다.</p><a href="#catalog" data-home class="outline-button">상품 둘러보기</a></div></section>`);
 panel.insertAdjacentHTML('beforeend',`<section class="account-section" id="my-profile" hidden><div class="account-section-head"><h2>회원정보 수정</h2><span>${user?'Google 로그인 계정':'로그인 필요'}</span></div><form id="account-profile-form" class="account-profile-form"><div class="form-grid"><label>닉네임<input name="nickname" maxlength="30" required value="${esc(profile.displayName||user?.displayName||'')}" placeholder="무드노트에서 사용할 이름"/></label><label>연락처<input name="profilePhone" type="tel" inputmode="tel" maxlength="20" pattern="(?:[0-9]{9,11}|[0-9]{2,3}-[0-9]{3,4}-[0-9]{4})" value="${esc(profile.phone||'')}" placeholder="010-0000-0000 (선택)"/></label><label class="wide">로그인 이메일<input type="email" value="${esc(user?.email||'')}" readonly placeholder="Google 로그인 후 표시됩니다"/></label></div><label class="profile-check"><input name="news" type="checkbox" ${profile.news?'checked':''}/> 새 상품·혜택 소식 받기</label><p class="delivery-note">닉네임·연락처·수신 설정은 로그인한 계정에 저장됩니다. Google 계정의 이름이나 이메일은 변경되지 않습니다.</p><button type="submit" class="solid-button">정보 저장</button><span id="profile-save-status" role="status"></span></form></section>`);
 renderInquiryPanel();
 const orderSection=document.getElementById('my-orders'),favoriteSection=document.getElementById('my-favorites'),couponSection=document.getElementById('my-coupons'),addressSection=document.getElementById('my-address'),profileSection=document.getElementById('my-profile');[orderSection,favoriteSection,couponSection,addressSection,profileSection].forEach(section=>panel.append(section));
 document.querySelector('#my-orders .account-section-head').insertAdjacentHTML('afterend','<label class="order-period">조회 기간<select id="order-period"><option value="all">전체 주문</option><option value="30">최근 1개월</option><option value="90">최근 3개월</option><option value="365">최근 1년</option></select></label><p id="order-filter-status" role="status" class="delivery-note"></p>');
 document.querySelectorAll('.account-order').forEach((el,index)=>{const order=(window.moodnoteOrders||[])[index];el.dataset.orderDate=orderDate(order).toISOString()});
}
document.addEventListener('submit',event=>{if(event.target.id!=='account-profile-form')return;event.preventDefault();const form=event.target,nickname=form.elements.nickname.value.trim();form.elements.nickname.setCustomValidity(nickname?'':'닉네임을 입력해주세요.');if(!form.reportValidity())return;if(!window.moodnoteData){toast('로그인 후 정보를 저장해주세요.');return}window.moodnoteData.saveProfile({displayName:nickname,phone:form.elements.profilePhone.value.trim(),news:form.elements.news.checked}).then(()=>{document.querySelector('.account-profile h2').textContent=nickname+'님, 반가워요.';document.getElementById('profile-save-status').textContent='정보를 저장했어요.';toast('회원정보를 저장했습니다.')}).catch(()=>toast('정보를 저장하지 못했습니다. 로그인 상태를 확인해주세요.'))});
document.addEventListener('input',event=>{if(event.target.closest('#account-profile-form'))event.target.setCustomValidity?.('')});
document.addEventListener('change',event=>{if(event.target.id!=='order-period')return;const days=event.target.value;let count=0;document.querySelectorAll('.account-order').forEach(el=>{el.hidden=days!=='all'&&Date.now()-new Date(el.dataset.orderDate).getTime()>Number(days)*86400000;if(!el.hidden)count++});document.getElementById('order-filter-status').textContent=count?`${count}건의 주문을 확인할 수 있어요.`:'선택한 기간에 주문 내역이 없어요.'});
